// Canonical reconstruction — NOT verbatim from the GSAP demo (CodePen returned 403)
const dock = document.querySelector('.dock');
const cards = gsap.utils.toArray('.dock .card');

const RADIUS = 200;        // px of influence on either side of cursor
const MAX_SCALE = 1.8;     // peak magnification at distance 0
const MAX_LIFT = 20;       // px the icon rises at distance 0

// Pre-bake high-throughput setters so we don't allocate a tween per move event
const setters = cards.map(card => ({
  scale: gsap.quickTo(card, 'scale', { duration: 0.3, ease: 'power2.out' }),
  y:     gsap.quickTo(card, 'y',     { duration: 0.3, ease: 'power2.out' }),
}));

// Cache card centers; refresh on resize so distance math stays correct
let centers = [];
const measure = () => {
  centers = cards.map(card => {
    const r = card.getBoundingClientRect();
    return r.left + r.width / 2;
  });
};
measure();
window.addEventListener('resize', measure);

dock.addEventListener('mousemove', (e) => {
  const x = e.clientX;
  for (let i = 0; i < cards.length; i++) {
    const dist = Math.abs(x - centers[i]);
    const t = Math.max(0, 1 - dist / RADIUS);     // 0..1 falloff
    setters[i].scale(1 + t * (MAX_SCALE - 1));
    setters[i].y(-t * MAX_LIFT);
  }
});

dock.addEventListener('mouseleave', () => {
  cards.forEach(card => {
    gsap.to(card, { scale: 1, y: 0, duration: 0.5, ease: 'power3.out', overwrite: 'auto' });
  });
});

/* CSS essentials
.dock { display: flex; align-items: flex-end; gap: 12px; padding: 12px; }
.dock .card { transform-origin: bottom center; will-change: transform; }
*/
